fn longest(words: &Vec<String>) -> usize {
    words.iter().map(|w| w.len()).max().unwrap_or(0)
}

fn main() {
    let words = vec![String::from("rope"), String::from("carabiner")];
    let n = longest(words);
    println!("{n} {}", words.len());
}

